for u,v,t in events:
    adj[u].append((v,t)); adj[v].append((u,t))
def closures(delta=800, lo=33039, hi=45039):
    out=[]
    for a,b,t3 in events:
        if not (lo<=t3<=hi): continue
        na={}; nb={}
        for x,tt in adj[a]:
            if tt<t3 and x!=b:
                na[x]=max(na.get(x,-1),tt) if False else min(na.get(x,10**9),tt) if False else tt
        # recompute: want any t1<t3 maximizing? use latest t1<t3
        na={}; nb={}
        for x,tt in adj[a]:
            if tt<t3 and x!=b: na[x]=max(na.get(x,-10**9),tt)
        for x,tt in adj[b]:
            if tt<t3 and x!=a: nb[x]=max(nb.get(x,-10**9),tt)
        for c in set(na)&set(nb):
            supp=max(na[c],nb[c])
            if t3-supp<=delta:
                out.append((a,b,t3,c,na[c],nb[c],t3-supp))
    return out
