def count_prompt(lo,hi,delta=800,filt=None):
    n=0; ex=[]
    for a,b,t3 in events:
        if not (lo<=t3<=hi): continue
        if filt and not filt(a,b): continue
        na={}; nb={}
        for x,tt in adj[a]:
            if tt<t3 and x!=b: na[x]=max(na.get(x,-10**9),tt)
        for x,tt in adj[b]:
            if tt<t3 and x!=a: nb[x]=max(nb.get(x,-10**9),tt)
        for c in set(na)&set(nb):
            if t3-max(na[c],nb[c])<=delta: n+=1; ex.append((a,b,t3,c))
    return n,ex
